<?php
declare(strict_types=1); require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Bootstrap\App; use App\Database\Database; use App\Modules\Customers\CustomerRepository; use App\Modules\Shops\ShopRepository; use App\Support\Auth; use function App\Support\e;
new App();$db=Database::connection();$merchant=Auth::requireMerchant($db);$shopId=(int)$merchant['id'];$id=(int)($_GET['id']??0);$repo=new CustomerRepository($db);$customer=$repo->findForShop($id,$shopId);if(!$customer){http_response_code(404);exit('Customer not found');}$orders=$repo->ordersForCustomer($id,$shopId);$shop=(new ShopRepository($db))->find($shopId);$merchantShop=$shop;$merchantSection='customers';$name=trim(($customer['first_name']??'').' '.($customer['last_name']??''))?:'Customer';ob_start();
?><div class="merchant-shell"><?php require dirname(__DIR__,2).'/app/Views/components/merchant-sidebar.php'; ?><main class="merchant-main"><div class="merchant-topbar"><div><a href="/customers" class="small text-secondary text-decoration-none"> Customers</a><h1 class="h3 fw-bold mb-0 mt-1"><?=e($name)?></h1></div></div><div class="row g-4"><div class="col-lg-4"><section class="panel p-4"><h2 class="h5 fw-bold">Customer details</h2><div class="mt-3"><div class="small text-secondary">Phone</div><div class="fw-semibold mt-1"><?=e($customer['phone'])?></div><?php if($customer['email']):?><div class="small text-secondary mt-3">Email</div><div class="fw-semibold mt-1"><?=e($customer['email'])?></div><?php endif;?></div><hr><div class="d-flex justify-content-between"><span class="small text-secondary">Orders</span><strong><?=number_format((int)$customer['total_orders'])?></strong></div><div class="d-flex justify-content-between mt-2"><span class="small text-secondary">Total spent</span><strong><?=e($shop['currency']??'KES')?> <?=number_format((float)$customer['total_spent'],2)?></strong></div></section></div><div class="col-lg-8"><section class="panel"><div class="panel-heading"><div><h2 class="h5 fw-bold mb-1">Order history</h2><p class="small text-secondary mb-0">Every order from this customer.</p></div></div><?php if(!$orders):?><div class="empty-state py-5"><p class="text-secondary mb-0">No orders found.</p></div><?php else:?><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($orders as $order):?><tr><td><a class="fw-semibold text-decoration-none" href="/orders/view?id=<?=(int)$order['id']?>">#<?=e($order['order_number'])?></a></td><td><?=e($order['currency'])?> <?=number_format((float)$order['total'],2)?></td><td><span class="status-badge status-<?=e($order['status'])?>"><?=e(ucfirst($order['status']))?></span></td><td class="small text-secondary"><?=e(date('d M Y, H:i',strtotime($order['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></div></main></div><?php $content=ob_get_clean();$title=$name;$merchantLayout=true;require dirname(__DIR__,2).'/app/Views/layouts/app.php';
